<template><div class="spotlight-products min-h-screen bg-[#f4f1ea] px-4 py-7 sm:py-12"><div class="mx-auto max-w-6xl"><div class="mb-6 flex items-end justify-between gap-4 border-b border-stone-300 pb-5 sm:mb-8"><h1 class="text-3xl font-black sm:text-4xl">{{ t('nav.products') }}</h1><RouterLink to="/" class="shrink-0 text-sm font-bold text-violet-700">{{ t('nav.home') }}</RouterLink></div><TemplateProductCollection :products="products" :mode="templateMode" grid-class="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3" @click="go" @quick-buy="quickBuy"/><ProductQuickBuy v-if="selected" :product="selected" :visible="quickVisible" @update:visible="quickVisible = $event" /></div></div></template>
<script setup lang="ts">import { computed, onMounted, onUnmounted, ref } from 'vue'; import { useI18n } from 'vue-i18n'; import { useRouter } from 'vue-router'; import { useProductList } from '../../composables/useProductList'; import { useAppStore } from '../../stores/app'; import TemplateProductCollection from '../components/TemplateProductCollection.vue'; import ProductQuickBuy from '../../components/ProductQuickBuy.vue'; const {t}=useI18n(); const router=useRouter(); const app=useAppStore(); const {products,initialize,cleanup}=useProductList({pageSize:30,homeRouteName:'products'}); const selected=ref<any>(null);const quickVisible=ref(false);const templateMode=computed<'card'|'list'>(()=>app.config?.template_mode==='list'?'list':'card');const go=(s:string)=>router.push(`/products/${s}`);const quickBuy=(p:any)=>{selected.value=p;quickVisible.value=true};onMounted(async()=>{await app.loadConfig();await initialize()});onUnmounted(cleanup)</script>
